var shippingPolicy = Policy
    .Handle<HttpRequestException>()
    .OrResult<ShippingLabel>(r => !r.Success)
    .CircuitBreakerAsync(
        handledEventsAllowedBeforeBreaking: 5,
        durationOfBreak: TimeSpan.FromSeconds(30));

var shippingResult = await shippingPolicy.ExecuteAsync(
    async () => await _shippingClient.CreateLabelAsync(order));

if (!shippingResult.Success)
{
    // Fallback: queue for manual review or async retry
    await _adminQueue.SendAsync(new ManualFulfillment(order));
    return Accepted(order.Id);
}

// Checkout API: synchronous payment, async fulfillment
[HttpPost]
public async Task<IActionResult> Checkout([FromBody] Order order)
{
    var payment = await _paymentService.ChargeAsync(order);
    if (!payment.Succeeded)
        return BadRequest(new { payment.Status });

    await _eventBus.PublishAsync(new OrderPaidEvent
    {
        OrderId = order.Id,
        Amount = payment.Amount
    });

    return Accepted(new { order.Id, Status = "processing" });
}

